//! Hand-written FFI bindings to LibRaw, pinned to the LibRaw **0.22** ABI
//! family (empirically measured and locked against 0.22.2).
//!
//! # Why hand-written, why pinned
//!
//! LuminaRust reads EXIF/metadata fields (`idata.make`, `other.*`,
//! `color.cam_mul` …) and writes processing parameters (`params.user_flip`,
//! `params.use_camera_wb`) through direct `#[repr(C)]` field access. Any drift
//! between these bindings and the linked library therefore silently corrupts
//! data (reads returned garbage into Sidecars; writes landed inside
//! `makernotes`, so `user_flip`/`use_camera_wb` were never applied). Accessor
//! functions alone cannot replace field access: the C API exposes setters for
//! only a handful of parameters and no accessors at all for most metadata
//! fields.
//!
//! The bindings are hence pinned to the 0.22 ABI family and enforced by three
//! layers derived from ONE source-of-truth table in `build.rs`:
//!
//! 1. **Build-time C gate**: `build.rs` emits `_Static_assert`s for every
//!    size/offset in the table and compiles them against the *actual* linked
//!    LibRaw headers. A mismatch aborts the build loudly.
//! 2. **Compile-time Rust gate**: the same table is emitted as Rust constants
//!    (`OUT_DIR/libraw_layout.rs`, re-exported as [`abi`]); `const` assertions
//!    below pin every struct definition to those numbers using
//!    `core::mem::size_of` / `core::mem::offset_of!`.
//! 3. **Runtime cross-check**: `tests/sizes.rs` compares the Rust-computed
//!    layout against the C-measured table at test time and asserts the linked
//!    library reports a `0.22.x` version.
//!
//! Vendor-specific makernote payloads (`libraw_makernotes_t`,
//! `libraw_shootinginfo_t`) are modelled as opaque byte padding: LuminaRust
//! never addresses their fields, they only contribute size/alignment inside
//! `libraw_data_t`, and their sizes are part of the enforced table.
#![allow(non_camel_case_types, non_snake_case, non_upper_case_globals)]

use libc::{c_char, c_double, c_float, c_int, c_longlong, c_short, c_uchar, c_uint, c_ulonglong, c_ushort, c_void, size_t, time_t};

/// Re-exported pinned-ABI constants generated by `build.rs`.
///
/// Every constant was empirically measured (sizeof/offsetof probe compiled
/// against the LibRaw 0.22.2 headers shipped by Homebrew and the pinned CI
/// container image). See the crate documentation for the enforcement layers.
pub mod abi {
    include!(concat!(env!("OUT_DIR"), "/libraw_layout.rs"));
}

#[repr(C)]
pub struct libraw_data_t {
    pub image: *mut [c_ushort; 4],
    pub sizes: libraw_image_sizes_t,
    pub idata: libraw_iparams_t,
    pub lens: libraw_lensinfo_t,
    /// Opaque stand-in for LibRaw's vendor-specific makernote payload. Never
    /// addressed; exists only to preserve offsets inside `libraw_data_t`.
    /// Size is enforced by the pinned-ABI table (`abi::SIZEOF_libraw_makernotes_t`).
    pub makernotes: libraw_makernotes_t,
    /// Opaque stand-in for LibRaw's `libraw_shootinginfo_t`; see `makernotes`.
    pub shootinginfo: libraw_shootinginfo_t,
    pub params: libraw_output_params_t,
    pub rawparams: libraw_raw_unpack_params_t,
    pub progress_flags: c_uint,
    pub process_warnings: c_uint,
    pub color: libraw_colordata_t,
    pub other: libraw_imgother_t,
    pub thumbnail: libraw_thumbnail_t,
    pub thumbs_list: libraw_thumbnail_list_t,
    pub rawdata: libraw_rawdata_t,
    pub parent_class: *mut c_void,
}

