/// Opaque stand-in for LibRaw's `libraw_makernotes_t` (vendor-specific
/// makernote payloads for Canon/Nikon/Sony/…). LuminaRust never reads or
/// writes these fields. The byte padding preserves size and alignment within
/// `libraw_data_t`; the exact size is part of the pinned-ABI table and is
/// verified at build time (C `_Static_assert`), compile time (Rust `const`
/// assert below) and test time (`tests/sizes.rs`).
///
/// To bind a specific makernote field, replace this padding with a faithful
/// `#[repr(C)]` transcription of the corresponding struct(s) from
/// `libraw/libraw_types.h` of the pinned LibRaw version and extend the table
/// in `build.rs`.
#[repr(C)]
pub struct libraw_makernotes_t {
    pub _opaque_padding: [u8; abi::SIZEOF_libraw_makernotes_t],
}

/// Opaque stand-in for LibRaw's `libraw_shootinginfo_t`; see
/// [`libraw_makernotes_t`] for the rationale.
#[repr(C)]
pub struct libraw_shootinginfo_t {
    pub _opaque_padding: [u8; abi::SIZEOF_libraw_shootinginfo_t],
}

