/// Compile-time enforcement of the pinned ABI (layer 2). Each assertion ties a
/// hand-written struct definition to a constant from the single-source table in
/// `build.rs`; the same table is `_Static_assert`ed against the real LibRaw
/// headers at build time (layer 1). Any drift — in the bindings *or* in the
/// linked library — breaks the build loudly instead of corrupting data.
mod pinned_abi_checks {
    use super::*;
    use std::mem::{offset_of, size_of};

    macro_rules! check_size {
        ($t:ty, $expected:ident) => {
            const _: () = assert!(size_of::<$t>() == abi::$expected);
        };
    }
    macro_rules! check_offset {
        ($t:ty, $field:ident, $expected:ident) => {
            const _: () = assert!(offset_of!($t, $field) == abi::$expected);
        };
    }

    // ---- sizes --------------------------------------------------------
    check_size!(libraw_data_t, SIZEOF_libraw_data_t);
    check_size!(libraw_image_sizes_t, SIZEOF_libraw_image_sizes_t);
    check_size!(libraw_iparams_t, SIZEOF_libraw_iparams_t);
    check_size!(libraw_lensinfo_t, SIZEOF_libraw_lensinfo_t);
    check_size!(libraw_nikonlens_t, SIZEOF_libraw_nikonlens_t);
    check_size!(libraw_dnglens_t, SIZEOF_libraw_dnglens_t);
    check_size!(libraw_makernotes_lens_t, SIZEOF_libraw_makernotes_lens_t);
    check_size!(libraw_makernotes_t, SIZEOF_libraw_makernotes_t);
    check_size!(libraw_shootinginfo_t, SIZEOF_libraw_shootinginfo_t);
    check_size!(libraw_output_params_t, SIZEOF_libraw_output_params_t);
    check_size!(libraw_raw_unpack_params_t, SIZEOF_libraw_raw_unpack_params_t);
    check_size!(ph1_t, SIZEOF_ph1_t);
    check_size!(libraw_dng_color_t, SIZEOF_libraw_dng_color_t);
    check_size!(libraw_dng_levels_t, SIZEOF_libraw_dng_levels_t);
    check_size!(libraw_P1_color_t, SIZEOF_libraw_P1_color_t);
    check_size!(libraw_colordata_t, SIZEOF_libraw_colordata_t);
    check_size!(libraw_gps_info_t, SIZEOF_libraw_gps_info_t);
    check_size!(libraw_imgother_t, SIZEOF_libraw_imgother_t);
    check_size!(libraw_thumbnail_t, SIZEOF_libraw_thumbnail_t);
    check_size!(libraw_thumbnail_item_t, SIZEOF_libraw_thumbnail_item_t);
    check_size!(libraw_thumbnail_list_t, SIZEOF_libraw_thumbnail_list_t);
    check_size!(libraw_internal_output_params_t, SIZEOF_libraw_internal_output_params_t);
    check_size!(libraw_rawdata_t, SIZEOF_libraw_rawdata_t);
    check_size!(libraw_processed_image_t, SIZEOF_libraw_processed_image_t);
    check_size!(libraw_decoder_info_t, SIZEOF_libraw_decoder_info_t);

    // ---- member offsets inside libraw_data_t --------------------------
    check_offset!(libraw_data_t, image, OFFSET_libraw_data_t_image);
    check_offset!(libraw_data_t, sizes, OFFSET_libraw_data_t_sizes);
    check_offset!(libraw_data_t, idata, OFFSET_libraw_data_t_idata);
    check_offset!(libraw_data_t, lens, OFFSET_libraw_data_t_lens);
    check_offset!(libraw_data_t, makernotes, OFFSET_libraw_data_t_makernotes);
    check_offset!(libraw_data_t, shootinginfo, OFFSET_libraw_data_t_shootinginfo);
    check_offset!(libraw_data_t, params, OFFSET_libraw_data_t_params);
    check_offset!(libraw_data_t, rawparams, OFFSET_libraw_data_t_rawparams);
    check_offset!(libraw_data_t, progress_flags, OFFSET_libraw_data_t_progress_flags);
    check_offset!(libraw_data_t, process_warnings, OFFSET_libraw_data_t_process_warnings);
    check_offset!(libraw_data_t, color, OFFSET_libraw_data_t_color);
    check_offset!(libraw_data_t, other, OFFSET_libraw_data_t_other);
    check_offset!(libraw_data_t, thumbnail, OFFSET_libraw_data_t_thumbnail);
    check_offset!(libraw_data_t, thumbs_list, OFFSET_libraw_data_t_thumbs_list);
    check_offset!(libraw_data_t, rawdata, OFFSET_libraw_data_t_rawdata);
    check_offset!(libraw_data_t, parent_class, OFFSET_libraw_data_t_parent_class);

    // ---- fields LuminaRust reads/writes -------------------------------
    check_offset!(libraw_image_sizes_t, flip, OFFSET_libraw_image_sizes_t_flip);
    check_offset!(libraw_iparams_t, make, OFFSET_libraw_iparams_t_make);
    check_offset!(libraw_iparams_t, model, OFFSET_libraw_iparams_t_model);
    check_offset!(libraw_output_params_t, use_camera_wb, OFFSET_libraw_output_params_t_use_camera_wb);
    check_offset!(libraw_output_params_t, use_camera_matrix, OFFSET_libraw_output_params_t_use_camera_matrix);
    check_offset!(libraw_output_params_t, user_flip, OFFSET_libraw_output_params_t_user_flip);
    check_offset!(libraw_output_params_t, output_bps, OFFSET_libraw_output_params_t_output_bps);
    check_offset!(libraw_output_params_t, output_color, OFFSET_libraw_output_params_t_output_color);
    check_offset!(libraw_output_params_t, no_auto_bright, OFFSET_libraw_output_params_t_no_auto_bright);
    check_offset!(libraw_colordata_t, curve, OFFSET_libraw_colordata_t_curve);
    check_offset!(libraw_colordata_t, cam_mul, OFFSET_libraw_colordata_t_cam_mul);
    check_offset!(libraw_colordata_t, pre_mul, OFFSET_libraw_colordata_t_pre_mul);
    check_offset!(libraw_colordata_t, rgb_cam, OFFSET_libraw_colordata_t_rgb_cam);
    check_offset!(libraw_colordata_t, profile, OFFSET_libraw_colordata_t_profile);
    check_offset!(libraw_colordata_t, profile_length, OFFSET_libraw_colordata_t_profile_length);
    check_offset!(libraw_imgother_t, iso_speed, OFFSET_libraw_imgother_t_iso_speed);
    check_offset!(libraw_imgother_t, shutter, OFFSET_libraw_imgother_t_shutter);
    check_offset!(libraw_imgother_t, aperture, OFFSET_libraw_imgother_t_aperture);
    check_offset!(libraw_imgother_t, focal_len, OFFSET_libraw_imgother_t_focal_len);
    check_offset!(libraw_imgother_t, timestamp, OFFSET_libraw_imgother_t_timestamp);
    check_offset!(libraw_imgother_t, desc, OFFSET_libraw_imgother_t_desc);
    check_offset!(libraw_imgother_t, artist, OFFSET_libraw_imgother_t_artist);
    check_offset!(libraw_rawdata_t, color, OFFSET_libraw_rawdata_t_color);
    check_offset!(libraw_processed_image_t, height, OFFSET_libraw_processed_image_t_height);
    check_offset!(libraw_processed_image_t, width, OFFSET_libraw_processed_image_t_width);
    check_offset!(libraw_processed_image_t, colors, OFFSET_libraw_processed_image_t_colors);
    check_offset!(libraw_processed_image_t, bits, OFFSET_libraw_processed_image_t_bits);
    check_offset!(libraw_processed_image_t, data_size, OFFSET_libraw_processed_image_t_data_size);
    check_offset!(libraw_processed_image_t, data, OFFSET_libraw_processed_image_t_data);
}
